import { forwardRef, useImperativeHandle, useMemo, useRef, useState } from 'react'
import { TouchableOpacity, View } from 'react-native'

import Popup, { type PopupType } from '@/components/common/Popup'
import Text from '@/components/common/Text'
import { Icon } from '@/components/common/Icon'
import { downloadMusic, getDownloadQualities } from '@/core/download'
import { useTheme } from '@/store/theme/hook'
import { createStyle } from '@/utils/tools'
import { Radius } from '@/theme/layout'

export interface DownloadQualityPickerType {
  show: (musicInfo: LX.Music.MusicInfoOnline) => void
}

export default forwardRef<DownloadQualityPickerType>((_, ref) => {
  const theme = useTheme()
  const popupRef = useRef<PopupType>(null)
  const [musicInfo, setMusicInfo] = useState<LX.Music.MusicInfoOnline | null>(null)
  const qualities = useMemo(() => musicInfo ? getDownloadQualities(musicInfo) : [], [musicInfo])

  useImperativeHandle(ref, () => ({
    show(info) {
      setMusicInfo(info)
      requestAnimationFrame(() => popupRef.current?.setVisible(true))
    },
  }))

  const handleSelect = (quality: LX.Quality) => {
    if (!musicInfo) return
    popupRef.current?.setVisible(false)
    void downloadMusic(musicInfo, quality)
  }

  return (
    <Popup ref={popupRef} title={global.i18n.t('download_quality_title')}>
      <View style={styles.content}>
        {musicInfo ? <View style={{ ...styles.track, backgroundColor: theme['c-primary-input-background'] }}>
          <View style={{ ...styles.trackIcon, backgroundColor: theme['c-primary-background-active'] }}>
            <Icon name="download-2" size={17} color={theme['c-primary-font-active']} />
          </View>
          <View style={styles.trackCopy}>
            <Text size={14} numberOfLines={1}>{musicInfo.name}</Text>
            {musicInfo.singer ? <Text size={11} color={theme['c-font-label']} numberOfLines={1}>{musicInfo.singer}</Text> : null}
          </View>
        </View> : null}
        <Text style={styles.hint} size={12} color={theme['c-font-label']}>{global.i18n.t('download_quality_available')}</Text>
        <View style={styles.qualityList}>
          {qualities.map(quality => <TouchableOpacity
            key={quality}
            accessibilityRole="button"
            accessibilityLabel={`${global.i18n.t('player_download')} ${quality}`}
            style={{ ...styles.qualityButton, backgroundColor: theme['c-primary-input-background'], borderColor: theme['c-border-background'] }}
            onPress={() => handleSelect(quality)}
          >
            <Text size={14}>{quality.toUpperCase()}</Text>
            <Icon name="chevron-right" size={11} color={theme['c-font-label']} />
          </TouchableOpacity>)}
        </View>
        {!qualities.length ? <Text style={styles.empty} size={12} color={theme['c-font-label']}>{global.i18n.t('download_quality_unavailable')}</Text> : null}
      </View>
    </Popup>
  )
})

const styles = createStyle({
  content: { paddingHorizontal: 16, paddingBottom: 24 },
  track: { minHeight: 58, borderRadius: Radius.card, paddingHorizontal: 12, flexDirection: 'row', alignItems: 'center' },
  trackIcon: { width: 36, height: 36, borderRadius: 12, alignItems: 'center', justifyContent: 'center' },
  trackCopy: { flex: 1, gap: 4, paddingLeft: 10 },
  hint: { paddingTop: 18, paddingBottom: 8, textAlign: 'center', textAlignVertical: 'center' },
  qualityList: { gap: 8 },
  qualityButton: { minHeight: 48, borderWidth: 1, borderRadius: Radius.control, paddingHorizontal: 15, flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between' },
  empty: { paddingVertical: 22, textAlign: 'center' },
})

import { useCallback, useMemo, useRef, useState, forwardRef, useImperativeHandle, useEffect } from 'react'
import { FlatList, type FlatListProps, RefreshControl, View, Platform } from 'react-native'

// import { useMusicList } from '@/store/list/hook'
import ListItem, { ITEM_HEIGHT } from './ListItem'
import { createStyle, getRowInfo, type RowInfoType } from '@/utils/tools'
import type { Position } from './ListMenu'
import type { SelectMode } from './MultipleModeBar'
import { useTheme } from '@/store/theme/hook'
import settingState from '@/store/setting/state'
import { MULTI_SELECT_BAR_HEIGHT } from './MultipleModeBar'
import { useI18n } from '@/lang'
import Text from '@/components/common/Text'
import Loading from '@/components/common/Loading'
import { Icon } from '@/components/common/Icon'
import RetryButton from '@/components/common/RetryButton'
import { handlePlay } from './listAction'
import { useSettingValue } from '@/store/setting/hook'

type FlatListType = FlatListProps<LX.Music.MusicInfoOnline>

export type {
  RowInfoType,
}

export interface ListProps {
  onShowMenu: (musicInfo: LX.Music.MusicInfoOnline, index: number, position: Position) => void
  onMuiltSelectMode: () => void
  onSelectAll: (isAll: boolean) => void
  onRefresh: () => void
  onLoadMore: () => void
  onPlayList?: (index: number) => void
  progressViewOffset?: number
  ListHeaderComponent?: FlatListType['ListEmptyComponent']
  checkHomePagerIdle: boolean
  rowType?: RowInfoType
}
export interface ListType {
  setList: (list: LX.Music.MusicInfoOnline[], isAppend: boolean, showSource: boolean) => void
  setIsMultiSelectMode: (isMultiSelectMode: boolean) => void
  setSelectMode: (mode: SelectMode) => void
  selectAll: (isAll: boolean) => void
  getSelectedList: () => LX.Music.MusicInfoOnline[]
  getList: () => LX.Music.MusicInfoOnline[]
  setStatus: (val: Status) => void
}
export type Status = 'loading' | 'refreshing' | 'end' | 'error' | 'idle'


const List = forwardRef<ListType, ListProps>(({
  onShowMenu,
  onMuiltSelectMode,
  onSelectAll,
  onRefresh,
  onLoadMore,
  onPlayList,
  progressViewOffset,
  ListHeaderComponent,
  checkHomePagerIdle,
  rowType,
}, ref) => {
  const t = useI18n()
  const theme = useTheme()
  const flatListRef = useRef<FlatList>(null)
  const [currentList, setList] = useState<LX.Music.MusicInfoOnline[]>([])
  const [showSource, setShowSource] = useState(false)
  const isMultiSelectModeRef = useRef(false)
  const selectModeRef = useRef<SelectMode>('single')
  const prevSelectIndexRef = useRef(-1)
  const [selectedList, setSelectedList] = useState<LX.Music.MusicInfoOnline[]>([])
  const selectedListRef = useRef<LX.Music.MusicInfoOnline[]>([])
  const selectedIds = useMemo(() => new Set(selectedList.map(item => item.id)), [selectedList])
  const [visibleMultiSelect, setVisibleMultiSelect] = useState(false)
  const [status, setStatus] = useState<Status>('idle')
  const rowInfo = useRef(getRowInfo(rowType))
  const isShowAlbumName = useSettingValue('list.isShowAlbumName')
  const isShowInterval = useSettingValue('list.isShowInterval')
  // const currentListIdRef = useRef('')
  // console.log('render music list')

  useImperativeHandle(ref, () => ({
    setList(list, isAppend, showSource) {
      setList(list)
      setShowSource(showSource)
      if (!isAppend && selectedListRef.current.length) setSelectedList(selectedListRef.current = [])
    },
    setIsMultiSelectMode(isMultiSelectMode) {
      isMultiSelectModeRef.current = isMultiSelectMode
      if (!isMultiSelectMode) {
        prevSelectIndexRef.current = -1
        handleUpdateSelectedList([])
      }
      setVisibleMultiSelect(isMultiSelectMode)
    },
    setSelectMode(mode) {
      selectModeRef.current = mode
    },
    selectAll(isAll) {
      let list: LX.Music.MusicInfoOnline[]
      if (isAll) {
        list = [...currentList]
      } else {
        list = []
      }
      selectedListRef.current = list
      setSelectedList(list)
    },
    getSelectedList() {
      return selectedListRef.current
    },
    getList() {
      return currentList
    },
    setStatus(val) {
      setStatus(val)
    },
  }))


  const handleUpdateSelectedList = (newList: LX.Music.MusicInfoOnline[]) => {
    if (selectedListRef.current.length && newList.length == currentList.length) onSelectAll(true)
    else if (selectedListRef.current.length == currentList.length) onSelectAll(false)
    selectedListRef.current = newList
    setSelectedList(newList)
  }
  const handleSelect = useCallback((item: LX.Music.MusicInfoOnline, pressIndex: number) => {
    let newList: LX.Music.MusicInfoOnline[]
    if (selectModeRef.current == 'single') {
      prevSelectIndexRef.current = pressIndex
      const index = selectedListRef.current.indexOf(item)
      if (index < 0) {
        newList = [...selectedListRef.current, item]
      } else {
        newList = [...selectedListRef.current]
        newList.splice(index, 1)
      }
    } else {
      if (selectedListRef.current.length) {
        const prevIndex = prevSelectIndexRef.current
        const currentIndex = pressIndex
        if (prevIndex == currentIndex) {
          newList = []
        } else if (currentIndex > prevIndex) {
          newList = currentList.slice(prevIndex, currentIndex + 1)
        } else {
          newList = currentList.slice(currentIndex, prevIndex + 1)
          newList.reverse()
        }
      } else {
        newList = [item]
        prevSelectIndexRef.current = pressIndex
      }
    }

    handleUpdateSelectedList(newList)
  }, [currentList, onSelectAll])

  const handlePress = useCallback((item: LX.Music.MusicInfoOnline, index: number) => {
    requestAnimationFrame(() => {
      if (checkHomePagerIdle && !global.lx.homePagerIdle) return
      if (isMultiSelectModeRef.current) {
        handleSelect(item, index)
      } else {
        if (settingState.setting['list.isClickPlayList'] && onPlayList != null) {
          onPlayList(index)
        } else {
          // console.log(currentList[index])
          handlePlay(currentList[index])
        }
      }
    })
  }, [checkHomePagerIdle, currentList, onPlayList, handleSelect])

  const handleLongPress = useCallback((item: LX.Music.MusicInfoOnline, index: number) => {
    if (isMultiSelectModeRef.current) return
    prevSelectIndexRef.current = index
    handleUpdateSelectedList([item])
    onMuiltSelectMode()
  }, [currentList, onMuiltSelectMode, handleSelect])

  const handleLoadMore = useCallback(() => {
    if (status != 'idle') return
    // Haptic feedback on load more trigger (using native bridge if available)
    if (Platform.OS === 'ios') {
      try {
        // Try to use native haptic feedback if available
        const { HapticFeedback } = require('react-native')
        if (HapticFeedback && HapticFeedback.impactAsync) {
          HapticFeedback.impactAsync('light')
        }
      } catch (e) {
        // Silently ignore if haptic feedback is not available
      }
    }
    onLoadMore()
  }, [status, onLoadMore])


  const renderItem = useCallback<NonNullable<FlatListType['renderItem']>>(({ item, index }) => (
    <ListItem
      item={item}
      index={index}
      showSource={showSource}
      onPress={handlePress}
      onLongPress={handleLongPress}
      onShowMenu={onShowMenu}
      selectedIds={selectedIds}
      rowInfo={rowInfo.current}
      isShowAlbumName={isShowAlbumName}
      isShowInterval={isShowInterval}
    />
  ), [showSource, handlePress, handleLongPress, onShowMenu, selectedList, isShowAlbumName, isShowInterval])
  const getkey = useCallback<NonNullable<FlatListType['keyExtractor']>>(item => item.id, [])
  const getItemLayout = useCallback<NonNullable<FlatListType['getItemLayout']>>((data, index) => {
    return { length: ITEM_HEIGHT, offset: ITEM_HEIGHT * index, index }
  }, [])
  const refreshControl = useMemo(() => (
    <RefreshControl
      colors={[theme['c-primary']]}
      progressBackgroundColor={theme['c-primary-input-background']}
      refreshing={status == 'refreshing'}
      onRefresh={onRefresh}
      progressViewOffset={20}
      tintColor={theme['c-primary']}
      title={t('pull_to_refresh')}
      titleColor={theme['c-font-label']} />
  ), [status, onRefresh, theme])
  const footerComponent = useMemo(() => {
    // 空列表时由空状态区负责反馈，避免空列表顶部出现游离的“加载中/到底啦”小字
    if (!currentList.length) return null
    let label: FooterLabel
    switch (status) {
      case 'refreshing': return null
      case 'loading':
        label = 'list_loading'
        break
      case 'end':
        label = 'list_end'
        break
      case 'error':
        label = 'list_error'
        break
      case 'idle':
        label = null
        break
    }
    return (
      <View style={{ width: '100%', paddingBottom: visibleMultiSelect ? MULTI_SELECT_BAR_HEIGHT : 0 }} >
        <Footer label={label} onLoadMore={onLoadMore} />
      </View>
    )
  }, [onLoadMore, status, visibleMultiSelect, currentList.length])

  const emptyComponent = useMemo(() => {
    if (currentList.length) return null
    switch (status) {
      case 'loading':
      case 'refreshing':
        return (
          <View style={styles.empty}>
            <Loading size={18} label={t('list_loading')} />
          </View>
        )
      case 'error':
        return (
          <View style={styles.empty}>
            <Text style={styles.emptyTitle} size={14} color={theme['c-font-label']}>{t('list_error')}</Text>
            <RetryButton label={t('retry_button_text')} onPress={onLoadMore} />
          </View>
        )
      case 'end':
        return (
          <View style={styles.empty}>
            <Icon name="album" size={28} color={theme['c-font-label']} style={styles.emptyIcon} />
            <Text style={styles.emptyTitle} size={14} color={theme['c-font-label']}>{t('no_item')}</Text>
          </View>
        )
      default: return null
    }
  }, [currentList.length, status, t, theme, onLoadMore])

  return (
    <FlatList
      ref={flatListRef}
      style={styles.list}
      data={currentList}
      numColumns={rowInfo.current.rowNum}
      horizontal={false}
      maxToRenderPerBatch={4}
      // updateCellsBatchingPeriod={80}
      windowSize={8}
      removeClippedSubviews={true}
      initialNumToRender={12}
      renderItem={renderItem}
      keyExtractor={getkey}
      getItemLayout={getItemLayout}
      // onRefresh={onRefresh}
      // refreshing={refreshing}
      onEndReachedThreshold={0.75}
      onEndReached={handleLoadMore}
      progressViewOffset={progressViewOffset}
      ListHeaderComponent={ListHeaderComponent}
      ListEmptyComponent={emptyComponent}
      refreshControl={refreshControl}
      ListFooterComponent={footerComponent}
    />
  )
})

type FooterLabel = 'list_loading' | 'list_end' | 'list_error' | null
const Footer = ({ label, onLoadMore }: {
  label: FooterLabel
  onLoadMore: () => void
}) => {
  const theme = useTheme()
  const t = useI18n()
  if (!label) return null
  if (label == 'list_loading') {
    return (
      <View style={styles.footerLoading}>
        <Loading size={15} label={t('list_loading')} />
      </View>
    )
  }
  if (label == 'list_error') {
    return (
      <View style={styles.footerError}>
        <Text style={styles.footerErrorText} size={13} color={theme['c-font-label']}>{t('list_error')}</Text>
        <RetryButton label={t('retry_button_text')} onPress={onLoadMore} />
      </View>
    )
  }
  return (
    <View>
      <Text style={styles.footer} size={12} color={theme['c-font-label']}>{t(label)}</Text>
    </View>
  )
}

const styles = createStyle({
  container: {
    flex: 1,
  },
  list: {
    flexGrow: 1,
    flexShrink: 1,
  },
  footer: {
    textAlign: 'center',
    padding: 10,
  },
  footerError: {
    paddingTop: 8,
    paddingBottom: 14,
    alignItems: 'center',
    gap: 10,
  },
  footerErrorText: {
    textAlign: 'center',
  },
  footerLoading: {
    paddingTop: 12,
    paddingBottom: 16,
    alignItems: 'center',
    justifyContent: 'center',
  },
  footerLoadingText: {
    fontSize: 11,
    color: 'transparent',
  },
  footerEnd: {
    paddingTop: 8,
    paddingBottom: 14,
    alignItems: 'center',
    gap: 10,
  },
  footerEndText: {
    fontSize: 12,
    textAlign: 'center',
    opacity: 0.9,
  },
  empty: {
    flexGrow: 1,
    minHeight: 220,
    alignItems: 'center',
    justifyContent: 'center',
    gap: 12,
    paddingVertical: 30,
  },
  emptyIcon: {
    opacity: 0.5,
  },
  emptyTitle: {
    opacity: 0.9,
  },
})

export default List

import { memo, useCallback, useRef, useEffect } from 'react'
import { type LayoutChangeEvent, StyleSheet, View, StatusBar, Dimensions } from 'react-native'
import commonState from '@/store/common/state'
import settingState from '@/store/setting/state'
import { setStatusbarHeight } from '@/core/common'
import { windowSizeTools, getWindowSize } from '@/utils/windowSizeTools'

const getStatusbarHeight = (winHeight: number, layoutHeight: number) => {
  const height = (!settingState.setting['common.alwaysKeepStatusbarHeight'] &&
          parseFloat(winHeight.toFixed(2)) >= parseFloat(layoutHeight.toFixed(2)))
    ? 0
    : (StatusBar.currentHeight ?? 0)

  return height
}

export default memo(() => {
  const currentHeightRef = useRef(commonState.statusbarHeight)
  const sizeRef = useRef([0, 0])
  const dimensionsChangedRef = useRef(true)
  const handleLayout = useCallback(({ nativeEvent: { layout } }: LayoutChangeEvent | { nativeEvent: { layout: { width: number, height: number } } }) => {
    // console.log('handleLayout')
    if (!layout || layout.width == null || layout.height == null) return
    if (!dimensionsChangedRef.current) return
    void getWindowSize().then(size => {
      dimensionsChangedRef.current = false
      // console.log(layout, size)
      sizeRef.current = [size.height, layout.height]
      const height = getStatusbarHeight(size.height, layout.height)

      if (currentHeightRef.current != height) {
        currentHeightRef.current = height
        setStatusbarHeight(height)
      }
      // console.log(layout, size)
      const currentSize = windowSizeTools.getSize()
      if (currentSize.width != layout.width || currentSize.height != layout.height) {
        windowSizeTools.setWindowSize(layout.width, layout.height)
      }
    })
  }, [])
  useEffect(() => {
    // let timeout: NodeJS.Timeout | null = null
    const subscription = Dimensions.addEventListener('change', () => {
      dimensionsChangedRef.current = true
      // if (timeout) clearTimeout(timeout)
      // timeout = setTimeout(() => {
      //   timeout = null
      //   viewRef.current?.measureInWindow((x, y, width, height) => {
      //     handleLayout({ nativeEvent: { layout: { width, height } } })
      //   })
      // }, 100)
    })

    const handleSettingUpdate = (keys: Array<keyof LX.AppSetting>) => {
      if (!keys.includes('common.alwaysKeepStatusbarHeight') || !sizeRef.current[1]) return
      const height = getStatusbarHeight(sizeRef.current[0], sizeRef.current[1])

      if (currentHeightRef.current != height) {
        currentHeightRef.current = height
        setStatusbarHeight(height)
      }
    }
    global.state_event.on('configUpdated', handleSettingUpdate)

    return () => {
      subscription.remove()
      global.state_event.off('configUpdated', handleSettingUpdate)
    }
  }, [])
  return (<View style={StyleSheet.absoluteFill} onLayout={handleLayout} />)
}, () => true)

export interface LxLyricWord {
  startTime: number
  duration: number
  text: string
}

export interface LxLyricLine {
  time: number
  text: string
  rawText: string
  extendedLyrics: string[]
  words: LxLyricWord[]
}

export interface LxLyricPlayState {
  line: number
  text: string
  wordIndex: number
  wordProgress: number
}

const noop = () => {}
const timeFieldExp = /^(?:\[[\d:.]+\])+/g
const timeExp = /\d{1,3}(:\d{1,3}){0,2}(?:\.\d{1,3})/g
const tagRegMap = {
  title: 'ti',
  artist: 'ar',
  album: 'al',
  offset: 'offset',
  by: 'by',
} as const
const wordTimeExp = /<(-?\d+),(-?\d+)>([^<]*)/g

const tRxp1 = /^0+(\d+)/
const tRxp2 = /:0+(\d+)/g
const tRxp3 = /\.0+(\d+)/

const formatTimeLabel = (label: string) => {
  return label.replace(tRxp1, '$1')
    .replace(tRxp2, ':$1')
    .replace(tRxp3, '.$1')
}

const parseLineWords = (text: string) => {
  const words: LxLyricWord[] = []
  let plainText = ''
  let match: RegExpExecArray | null
  while ((match = wordTimeExp.exec(text)) != null) {
    const word = match[3] ?? ''
    words.push({
      startTime: parseInt(match[1]),
      duration: parseInt(match[2]),
      text: word,
    })
    plainText += word
  }
  wordTimeExp.lastIndex = 0
  return {
    words,
    text: words.length ? plainText : text,
  }
}

const parseExtendedLyric = (lrcLinesMap: Record<string, LxLyricLine>, extendedLyric: string) => {
  const extendedLines = extendedLyric.split(/\r\n|\n|\r/)
  for (const rawLine of extendedLines) {
    const line = rawLine.trim()
    const result = timeFieldExp.exec(line)
    if (!result) continue

    const timeField = result[0]
    const text = line.replace(timeFieldExp, '').trim()
    if (!text) continue
    const { text: displayText } = parseLineWords(text)
    if (!displayText) continue

    const times = timeField.match(timeExp)
    if (times == null) continue
    for (let time of times) {
      time = formatTimeLabel(time)
      const targetLine = lrcLinesMap[time]
      if (targetLine) targetLine.extendedLyrics.push(displayText)
    }
  }
}

const getNow = () => Date.now()

export default class LxLyricPlayer {
  lyric = ''
  extendedLyrics: string[] = []
  tags: Record<string, string | number> = {}
  lines: LxLyricLine[] = []
  onPlay: (line: number, text: string, wordIndex: number, wordProgress: number) => void
  onSetLyric: (lines: LxLyricLine[]) => void
  isPlay = false
  curLineNum = 0
  curWordIndex = -1
  maxLine = 0
  offset = 100
  private _performanceTime = 0
  private _startTime = 0
  private _rate = 1
  private timeoutId: ReturnType<typeof setTimeout> | null = null

  constructor({
    lyric = '',
    extendedLyrics = [],
    offset = 100,
    playbackRate = 1,
    onPlay = noop,
    onSetLyric = noop,
  }: {
    lyric?: string
    extendedLyrics?: string[]
    offset?: number
    playbackRate?: number
    onPlay?: (line: number, text: string, wordIndex: number, wordProgress: number) => void
    onSetLyric?: (lines: LxLyricLine[]) => void
  } = {}) {
    this.lyric = lyric
    this.extendedLyrics = extendedLyrics
    this.offset = offset
    this._rate = playbackRate
    this.onPlay = onPlay
    this.onSetLyric = onSetLyric
  }

  private clearTimer() {
    if (this.timeoutId == null) return
    clearTimeout(this.timeoutId)
    this.timeoutId = null
  }

  private getLineEndTime(index: number) {
    const line = this.lines[index]
    if (!line) return 0
    const lastWord = line.words.at(-1)
    if (lastWord) return line.time + lastWord.startTime + lastWord.duration
    const nextLine = this.lines[index + 1]
    if (nextLine) return nextLine.time - 30
    return line.time + 3000
  }

  private getWordState(lineIndex: number, currentTime: number) {
    const line = this.lines[lineIndex]
    if (!line || !line.words.length) return { index: -1, progress: 0 }
    const elapsed = currentTime - line.time
    if (elapsed < 0) return { index: -1, progress: 0 }
    for (let i = 0; i < line.words.length; i++) {
      const word = line.words[i]
      if (elapsed < word.startTime) return { index: Math.max(i - 1, -1), progress: 1 }
      if (elapsed <= word.startTime + word.duration) {
        const progress = word.duration > 0 ? Math.min(Math.max((elapsed - word.startTime) / word.duration, 0), 1) : 1
        return { index: i, progress }
      }
    }
    return { index: line.words.length - 1, progress: 1 }
  }

  private emitState(currentTime: number) {
    if (!this.lines.length) {
      if (this.curLineNum != -1 || this.curWordIndex != -1) {
        this.curLineNum = -1
        this.curWordIndex = -1
        this.onPlay(-1, '', -1, 0)
      }
      return
    }
    const lineIndex = this.findCurLineNum(currentTime)
    const { index: wordIndex, progress: wordProgress } = this.getWordState(lineIndex, currentTime)
    if (this.curLineNum == lineIndex && this.curWordIndex == wordIndex && this.curWordIndex > -1) {
      this.onPlay(lineIndex, this.lines[lineIndex]?.text ?? '', wordIndex, wordProgress)
      return
    }
    if (this.curLineNum == lineIndex && this.curWordIndex == wordIndex) return
    this.curLineNum = lineIndex
    this.curWordIndex = wordIndex
    this.onPlay(lineIndex, this.lines[lineIndex]?.text ?? '', wordIndex, wordProgress)
  }

  private tick() {
    if (!this.isPlay) return
    const currentTime = this.currentTime()
    this.emitState(currentTime)
    if (this.maxLine >= 0 && currentTime > this.getLineEndTime(this.maxLine)) {
      this.pause()
      return
    }
    this.timeoutId = setTimeout(() => {
      this.tick()
    }, 50)
  }

  private initTag() {
    this.tags = {}
    for (const tag in tagRegMap) {
      const matches = this.lyric.match(new RegExp(`\\[${tagRegMap[tag as keyof typeof tagRegMap]}:([^\\]]*)]`, 'i'))
      this.tags[tag] = (matches && matches[1]) || ''
    }
    if (this.tags.offset) {
      const parsedOffset = parseInt(this.tags.offset as string)
      this.tags.offset = Number.isNaN(parsedOffset) ? 0 : parsedOffset
    } else this.tags.offset = 0
  }

  private initLines() {
    this.lines = []
    const lines = this.lyric.split(/\r\n|\n|\r/)
    const linesMap: Record<string, LxLyricLine> = {}
    for (const rawLine of lines) {
      const line = rawLine.trim()
      const result = timeFieldExp.exec(line)
      if (!result) continue

      const timeField = result[0]
      const text = line.replace(timeFieldExp, '').trim()
      if (!text) continue

      const times = timeField.match(timeExp)
      if (times == null) continue
      for (let time of times) {
        time = formatTimeLabel(time)
        const { words, text: displayText } = parseLineWords(text)
        if (linesMap[time]) {
          linesMap[time].extendedLyrics.push(displayText)
          continue
        }
        const timeArr = time.split(':')
        if (timeArr.length > 3) continue
        if (timeArr.length < 3) {
          for (let i = 3 - timeArr.length; i--;) timeArr.unshift('0')
        }
        if (timeArr[2].includes('.')) timeArr.splice(2, 1, ...timeArr[2].split('.'))

        linesMap[time] = {
          time: parseInt(timeArr[0]) * 60 * 60 * 1000 + parseInt(timeArr[1]) * 60 * 1000 + parseInt(timeArr[2]) * 1000 + parseInt(timeArr[3] || '0'),
          text: displayText,
          rawText: text,
          extendedLyrics: [],
          words,
        }
      }
    }

    for (const lrc of this.extendedLyrics) parseExtendedLyric(linesMap, lrc)
    this.lines = Object.values(linesMap).sort((a, b) => a.time - b.time)
    this.maxLine = this.lines.length - 1
  }

  private currentTime() {
    return (getNow() - this._performanceTime) * this._rate + this._startTime
  }

  private findCurLineNum(curTime: number, startIndex = 0) {
    if (curTime <= 0) return 0
    const length = this.lines.length
    for (let index = startIndex; index < length; index++) {
      if (curTime <= this.lines[index].time) return index === 0 ? 0 : index - 1
    }
    return length - 1
  }

  setPlaybackRate(rate: number) {
    this._rate = rate
    if (!this.lines.length || !this.isPlay) return
    this.play(this.currentTime())
  }

  setLyric(lyric: string, extendedLyrics: string[] = []) {
    if (this.isPlay) this.pause()
    this.lyric = lyric ?? ''
    this.extendedLyrics = extendedLyrics ?? []
    this.initTag()
    this.initLines()
    this.curLineNum = 0
    this.curWordIndex = -1
    this.onSetLyric(this.lines)
  }

  play(curTime = 0) {
    if (!this.lines.length) return
    this.pause()
    this.isPlay = true
    this._performanceTime = getNow() - Math.trunc((this.tags.offset as number) + this.offset)
    this._startTime = curTime
    this.curLineNum = -1
    this.curWordIndex = -1
    this.tick()
  }

  pause() {
    if (!this.isPlay) return
    this.isPlay = false
    this.clearTimer()
    this.emitState(this.currentTime())
  }
}

import { useEffect, useState } from 'react'
import { StyleSheet, TouchableOpacity, View } from 'react-native'

import Text from '@/components/common/Text'
import { Icon } from '@/components/common/Icon'
import {
  cancelDownloadTask,
  removeDownloadTask,
  retryDownloadTask,
  subscribeDownloadTasks,
  type DownloadTask,
} from '@/core/download'
import { createStyle } from '@/utils/tools'
import { useTheme } from '@/store/theme/hook'
import { Radius } from '@/theme/layout'

type QueueStatusLabel = 'download_queue_queued' | 'download_queue_downloading' | 'download_queue_completed' | 'download_queue_failed' | 'download_queue_canceled'

const statusKeys: Record<DownloadTask['status'], QueueStatusLabel> = {
  queued: 'download_queue_queued',
  downloading: 'download_queue_downloading',
  completed: 'download_queue_completed',
  failed: 'download_queue_failed',
  canceled: 'download_queue_canceled',
}

const formatSize = (size: number) => {
  if (size < 1024 * 1024) return `${Math.max(1, Math.round(size / 1024))} KB`
  return `${(size / 1024 / 1024).toFixed(size >= 100 * 1024 * 1024 ? 0 : 1)} MB`
}

export default () => {
  const theme = useTheme()
  const [tasks, setTasks] = useState<DownloadTask[]>([])

  useEffect(() => subscribeDownloadTasks(allTasks => {
    setTasks(allTasks.filter(task => task.status != 'completed').slice(0, 3))
  }), [])

  if (!tasks.length) return null

  return (
    <View style={styles.container}>
      <Text style={styles.title} size={12} color={theme['c-font-label']}>{global.i18n.t('download_queue_title')}</Text>
      {tasks.map(task => (
        <View key={task.id} style={{ ...styles.task, borderColor: theme['c-border-background'] }}>
          <View style={{ ...styles.taskIcon, backgroundColor: theme['c-primary-background-active'] }}>
            <Icon name="download-2" size={15} color={theme['c-primary-font-active']} />
          </View>
          <View style={styles.taskCopy}>
            <Text size={13} numberOfLines={1}>{task.name}{task.singer ? ` - ${task.singer}` : ''}</Text>
            <Text size={11} color={theme['c-font-label']} numberOfLines={1}>
              {global.i18n.t(statusKeys[task.status])}
              {task.quality ? ` · ${task.quality.toUpperCase()}` : ''}
              {task.status == 'downloading' && task.totalBytes > 0 ? ` · ${Math.round(task.progress * 100)}%` : ''}
              {task.status == 'downloading' && task.totalBytes > 0 ? ` · ${formatSize(task.receivedBytes)}/${formatSize(task.totalBytes)}` : ''}
            </Text>
            {task.status == 'downloading' ? (
              <View style={{ ...styles.progressTrack, backgroundColor: theme['c-primary-input-background'] }}>
                <View style={{
                  ...styles.progressValue,
                  width: `${Math.max(2, Math.round(task.progress * 100))}%`,
                  backgroundColor: theme['c-primary'],
                }} />
              </View>
            ) : null}
          </View>
          {task.status == 'failed' ? (
            <TouchableOpacity
              accessibilityRole="button"
              accessibilityLabel={global.i18n.t('download_queue_retry')}
              style={styles.action}
              hitSlop={{ top: 5, bottom: 5, left: 5, right: 5 }}
              onPress={() => retryDownloadTask(task.id)}
            >
              <Icon name="download-2" size={14} color={theme['c-font']} />
            </TouchableOpacity>
          ) : null}
          {task.status == 'queued' || task.status == 'downloading' ? (
            <TouchableOpacity
              accessibilityRole="button"
              accessibilityLabel={global.i18n.t('download_queue_cancel')}
              style={styles.action}
              hitSlop={{ top: 5, bottom: 5, left: 5, right: 5 }}
              onPress={() => cancelDownloadTask(task.id)}
            >
              <Icon name="close" size={13} color={theme['c-font-label']} />
            </TouchableOpacity>
          ) : null}
          {task.status == 'canceled' ? (
            <TouchableOpacity
              accessibilityRole="button"
              accessibilityLabel={global.i18n.t('delete')}
              style={styles.action}
              hitSlop={{ top: 5, bottom: 5, left: 5, right: 5 }}
              onPress={() => removeDownloadTask(task.id)}
            >
              <Icon name="remove" size={13} color={theme['c-font-label']} />
            </TouchableOpacity>
          ) : null}
        </View>
      ))}
    </View>
  )
}

