  return (
    <View style={{ ...styles.library, borderBottomColor: theme['c-border-background'] }}>
      <View style={styles.libraryHeader}>
        <Text size={11} color={theme['c-font-label']}>{global.i18n.t('list_total', { num: allList.length })}</Text>
